/* Visual sign-in only. No server, real credentials or access control. */
const DEMO_ADMIN_EMAIL='gestao@maosemoracao.demo',DEMO_ADMIN_PASSWORD='Essencia3D!';
let adminDemoSession=null,authMode='login',authReturn='#/admin',authEmail='',authLastView='',authKind='',authKeyboardAt=0;
try{adminDemoSession=JSON.parse(sessionStorage.getItem('amago-admin-session'));if(adminDemoSession?.email==='gestao@amago3d.demo'){adminDemoSession.email=DEMO_ADMIN_EMAIL;adminDemoSession.name='Equipe Mãos em Oração';sessionStorage.setItem('amago-admin-session',JSON.stringify(adminDemoSession))}}catch{}
if(readStore('auth-email-admin','')==='gestao@amago3d.demo')persist('auth-email-admin',DEMO_ADMIN_EMAIL);
function adminSessionActive(){return adminDemoSession?.demo===true&&adminDemoSession.email===DEMO_ADMIN_EMAIL}
function authenticateAdminDemo(email,password,remember=false){if(email.trim().toLowerCase()!==DEMO_ADMIN_EMAIL||password!==DEMO_ADMIN_PASSWORD)return false;adminDemoSession={demo:true,email:DEMO_ADMIN_EMAIL,name:'Equipe Mãos em Oração',startedAt:new Date().toISOString()};try{sessionStorage.setItem('amago-admin-session',JSON.stringify(adminDemoSession))}catch{}if(remember)persist('auth-email-admin',DEMO_ADMIN_EMAIL);else persist('auth-email-admin','');return true}
function endAdminDemoSession(){adminDemoSession=null;try{sessionStorage.removeItem('amago-admin-session')}catch{}}
function safeAdminDestination(route){return /^#\/admin(?:\/[a-zA-Z0-9_-]+)*$/.test(route)&&!route.startsWith('#/admin/login')?route:'#/admin'}
paths.eye='M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0';
paths.eyeOff='m3 3 18 18M9.9 5.2A12 12 0 0 1 12 5c6.5 0 10 7 10 7a17 17 0 0 1-3 3.9M6 6.8A18 18 0 0 0 2 12s3.5 7 10 7a12 12 0 0 0 5.1-1.2M10 10a3 3 0 0 0 4 4';
function adminEntryPage(route){const login=route[0]==='login'||!adminSessionActive();document.body.classList.toggle('auth-mode',login);if(login){if(route[0]!=='login')authReturn=safeAdminDestination('#/admin'+(route.length?'/'+route.join('/'):''));document.title='Entrar na gestão · Mãos em Oração';return authPage('admin')}return adminShell(route)}
function authPage(kind='customer'){
 if(authKind!==kind){authKind=kind;authMode='login';authEmail='';authLastView=''}
 const admin=kind==='admin',recover=authMode==='recover',register=!admin&&authMode==='register';
 const title=recover?'Vamos reencontrar o caminho.':register?'Faça parte deste cantinho.':'Bem-vindo de volta.';
 const intro=recover?'Informe seu e-mail fictício para conhecer a recuperação de acesso.':register?'Crie seu espaço para guardar escolhas e acompanhar cada nova história.':admin?'Entre para cuidar da loja e de cada nova história.':'Seu espaço para acompanhar pedidos, cuidar da assinatura e guardar o que toca você.';
 const email=authEmail||readStore('auth-email-'+kind,'');
 return `<div class="auth-page" data-auth-kind="${kind}"><header class="auth-header">${logo()}<a href="#/" class="auth-back">Voltar para a loja ${icon('arrow')}</a></header><main id="main" class="auth-layout"><aside class="auth-story" aria-label="A fé ganha forma"><div class="auth-photograph"><img src="assets/faith-home.png" alt="Mãos sobre uma Bíblia aberta, com uma cruz e a palavra Fé em uma mesa iluminada" fetchpriority="high"><span>Imagem conceitual · Mãos em Oração</span></div><div class="auth-story-copy"><h2>O cuidado também<br>é uma forma <em>de fé.</em></h2><p>${admin?'Por trás de cada peça, existe uma história. E alguém cuidando de cada detalhe.':'Pequenos lembretes de um amor maior. Perto de você, em cada novo capítulo.'}</p><div class="auth-story-signature">${icon('heart')}Fé para viver. Amor para compartilhar.</div></div></aside><section class="auth-form-region"><div class="auth-form-wrap"><nav class="auth-audience" aria-label="Tipo de acesso"><a href="#/login" ${!admin?'aria-current="page"':''}>Sou cliente</a><a href="#/admin/login" ${admin?'aria-current="page"':''}>Sou da equipe ${icon('lock')}</a></nav><div class="auth-form-content"><h1>${title}</h1><p class="auth-intro">${intro}</p>${recover?`<form data-auth-form="recover" class="auth-form" data-kind="${kind}"><label for="auth-email">E-mail de demonstração</label><div class="auth-input">${icon('mail')}<input id="auth-email" name="email" type="email" required autocomplete="off" value="${esc(email)}" placeholder="${admin?DEMO_ADMIN_EMAIL:'seunome@exemplo.com'}"></div><p class="auth-caption">Esta é uma simulação. Nenhum e-mail será enviado.</p><button class="btn auth-submit">Simular recuperação ${icon('arrow')}</button><div id="auth-feedback" class="auth-feedback" role="status"></div></form><button class="auth-return text-btn" data-auth="mode" data-mode="login">Voltar ao login</button>`:`${!admin?`<div class="auth-account-tabs" role="group" aria-label="Acesso da conta"><button data-auth="mode" data-mode="login" aria-pressed="${!register}">Entrar</button><button data-auth="mode" data-mode="register" aria-pressed="${register}">Criar conta</button></div>`:''}<form data-auth-form="${kind}" class="auth-form" novalidate>${register?`<label for="auth-name">Como podemos chamar você?</label><div class="auth-input">${icon('user')}<input id="auth-name" name="name" required minlength="2" autocomplete="off" placeholder="Seu nome fictício"></div>`:''}<label for="auth-email">E-mail de demonstração</label><div class="auth-input">${icon('mail')}<input id="auth-email" name="email" type="email" required autocomplete="off" value="${esc(email)}" placeholder="${admin?DEMO_ADMIN_EMAIL:'seunome@exemplo.com'}" aria-describedby="auth-error"></div><div class="auth-label-row"><label for="auth-password">Senha fictícia</label><button type="button" data-auth="mode" data-mode="recover">Esqueci minha senha</button></div><div class="auth-input">${icon('lock')}<input id="auth-password" name="password" type="password" required minlength="${admin?8:4}" autocomplete="off" placeholder="${admin?'Senha do acesso de teste':'Crie uma senha fictícia'}" aria-describedby="auth-error"><button class="auth-eye" type="button" data-auth="password" aria-label="Mostrar senha" aria-pressed="false">${icon('eye')}</button></div><label class="auth-remember"><input type="checkbox" name="remember" ${email?'checked':''}>Lembrar meu e-mail neste navegador</label><p id="auth-error" class="auth-error" role="alert" tabindex="-1"></p><button class="btn auth-submit">${admin?'Entrar na gestão':register?'Criar minha conta':'Entrar na minha conta'} ${icon('arrow')}</button></form><div class="auth-demo-divider"><span>Conheça por dentro</span></div><button class="btn secondary auth-demo-button" data-auth="demo" data-kind="${kind}">${icon('spark')}${admin?'Preencher acesso de demonstração':'Explorar com uma conta de teste'}</button>${admin?`<p class="auth-demo-credentials">Acesso de teste: <strong>${DEMO_ADMIN_EMAIL}</strong></p>`:''}`}</div><p class="auth-local-note">${icon('shield')}<span>Protótipo visual · use apenas dados fictícios.<br>O login é simulado e não protege dados reais.</span></p></div><footer class="auth-footer"><span>Mãos em Oração · Essência</span><a href="#/suporte/privacidade">Privacidade e dados</a></footer></section></main></div>`
}
function animateAuthEntry(){const page=$('.auth-page');if(!page){authLastView='';return}const key=page.dataset.authKind+':'+authMode;if(key===authLastView)return;authLastView=key;if(Date.now()-authKeyboardAt<1000)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const node=$('.auth-form-content',page);node.animate(reduced?[{opacity:.8},{opacity:1}]:[{opacity:.55,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:reduced?100:240,easing:'cubic-bezier(.23,1,.32,1)'});if(!reduced&&authMode==='login')$('.auth-photograph',page).animate([{clipPath:'inset(0 0 4% 0)',transform:'translateY(6px)'},{clipPath:'inset(0 0 0 0)',transform:'translateY(0)'}],{duration:280,easing:'cubic-bezier(.23,1,.32,1)'})}
function authError(message,field){const box=$('#auth-error');if(!box)return;box.textContent=message;if(field)field.setAttribute('aria-invalid','true');box.focus();if(!matchMedia('(prefers-reduced-motion: reduce)').matches)box.animate([{opacity:.4},{opacity:1}],{duration:150,easing:'cubic-bezier(.23,1,.32,1)'})}
document.addEventListener('keydown',e=>{if(['Tab','Enter',' '].includes(e.key))authKeyboardAt=Date.now()},{capture:true});
document.addEventListener('click',e=>{const b=e.target.closest('[data-auth]');if(!b)return;const action=b.dataset.auth;
 if(action==='mode'){authEmail=$('#auth-email')?.value||'';authMode=b.dataset.mode;render()}
 if(action==='password'){const input=$('#auth-password'),show=input.type==='password';input.type=show?'text':'password';b.setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha');b.setAttribute('aria-pressed',String(show));b.innerHTML=icon(show?'eyeOff':'eye');input.focus()}
 if(action==='demo'){if(b.dataset.kind==='admin'){authMode='login';if(!$('[data-auth-form=admin]'))render();$('#auth-email').value=DEMO_ADMIN_EMAIL;$('#auth-password').value=DEMO_ADMIN_PASSWORD;$('#auth-password').type='password';$('.auth-eye').setAttribute('aria-label','Mostrar senha');$('.auth-eye').setAttribute('aria-pressed','false');$('.auth-eye').innerHTML=icon('eye');$('#auth-error').textContent='';$$('[aria-invalid]').forEach(x=>x.removeAttribute('aria-invalid'));$('.auth-submit').focus();toast('Acesso de teste preenchido. Clique em Entrar na gestão.')}else{guestLogin();if(location.hash==='#/login')navigate('#/conta');toast('Conta de teste aberta.')}}
 if(action==='logout-admin'){endAdminDemoSession();authMode='login';authEmail='';navigate('#/admin/login');render();toast('Você saiu da gestão de demonstração.')}
});
document.addEventListener('input',e=>{if(!e.target.closest('[data-auth-form]'))return;e.target.removeAttribute('aria-invalid');const error=$('#auth-error');if(error)error.textContent=''});
document.addEventListener('submit',e=>{const f=e.target,kind=f.dataset.authForm;if(!kind)return;e.preventDefault();const d=Object.fromEntries(new FormData(f));
 if(kind==='recover'){if(!f.reportValidity())return;const output=$('#auth-feedback');output.innerHTML=`${icon('check')}<span>Simulação concluída para ${esc(d.email)}. Nenhum e-mail foi enviado. ${f.dataset.kind==='admin'?'Volte ao login e use o acesso de demonstração.':'Volte ao login e use qualquer senha fictícia com pelo menos 4 caracteres.'}</span>`;f.querySelector('button[type=submit],.auth-submit').disabled=true;return}
 if(!f.checkValidity()){const invalid=$(':invalid',f);const message=invalid?.name==='email'?'Informe um e-mail de demonstração válido.':invalid?.name==='name'?'Informe um nome fictício com pelo menos 2 caracteres.':`Use uma senha fictícia com pelo menos ${kind==='admin'?8:4} caracteres.`;authError(message,invalid);return}
 if(kind==='admin'){if(!authenticateAdminDemo(d.email,d.password,!!d.remember)){authError('Acesso não reconhecido. Use “Preencher acesso de demonstração” para explorar a gestão.',$('#auth-password'));return}authEmail='';authMode='login';authLastView='';navigate(safeAdminDestination(authReturn));render();toast('Bem-vindo à gestão de demonstração.');return}
 const existing=typeof ops!=='undefined'?ops.clients.find(c=>c.email.toLowerCase()===d.email.toLowerCase()):null;customer={name:d.name||existing?.name||'Cliente de demonstração',email:d.email,...(existing?{clubCustomerId:existing.id}:{})};persist('customer',customer);persist('auth-email-customer',d.remember?d.email:'');authMode='login';authEmail='';authLastView='';if(location.hash==='#/login')navigate('#/conta');render();toast('Seu espaço de demonstração está pronto.');
});
